/**
 * MEDIA STORE
 * ===========
 * The canonical record of what image a user or a room uses.
 *
 * TWO PLACES, ONE RULE
 * ---------------------
 *   - a user's avatar lives on their PROFILE document: `users/{uid}.photo`
 *   - a room's cover lives on the ROOM document:     `goatTeams/{roomId}.cover`
 *
 * Both store the R2 OBJECT KEY plus its metadata. They never store a URL:
 * a signed delivery url expires, so a stored url would be a broken image
 * tomorrow. The url is regenerated by the server on every read, which is also
 * what lets a private room's cover stop being reachable the moment the
 * viewer loses access.
 *
 * Firestore in production, a JSON file for self-hosted runs.
 */

import fs from "node:fs";
import path from "node:path";
import type { Firestore } from "firebase-admin/firestore";
import { getFirebaseAdmin } from "../firebaseAdmin";
import { firestoreSafe } from "../repositories";
import type { MediaPurpose, MediaReference } from "../../types/rooms";
import { createDeliveryUrl } from "./mediaSigner";

export interface StoredMedia {
  key: string;
  contentType: string;
  size: number;
  updatedAt: string;
}

interface MediaDb {
  avatars: Record<string, StoredMedia>;
  covers: Record<string, StoredMedia>;
}

const emptyDb = (): MediaDb => ({ avatars: {}, covers: {} });

const safeId = (value: string) =>
  value.replace(/[^A-Za-z0-9_-]/g, "_").slice(0, 200);

export class MediaStore {
  private readonly firestore?: Firestore;
  private readonly filePath: string;
  private db: MediaDb = emptyDb();

  constructor(options: { firestore?: Firestore; filePath?: string } = {}) {
    this.firestore = options.firestore;
    this.filePath =
      options.filePath ||
      path.join(
        process.env.DATA_DIR || path.join(process.cwd(), "data"),
        "room-media.json",
      );
    if (!this.firestore) {
      fs.mkdirSync(path.dirname(this.filePath), { recursive: true });
      try {
        if (fs.existsSync(this.filePath)) {
          this.db = {
            ...emptyDb(),
            ...(JSON.parse(fs.readFileSync(this.filePath, "utf8")) as Partial<MediaDb>),
          };
        }
      } catch (error) {
        throw new Error("MEDIA_STORE_UNREADABLE: saved media references could not be loaded.", {
          cause: error,
        });
      }
    }
  }

  private persist() {
    fs.mkdirSync(path.dirname(this.filePath), { recursive: true });
    const temp = this.filePath + ".tmp";
    fs.writeFileSync(temp, JSON.stringify(this.db), "utf8");
    fs.renameSync(temp, this.filePath);
  }

  // -- avatars ------------------------------------------------------------

  async getAvatar(uid: string): Promise<StoredMedia | null> {
    if (this.firestore) {
      const snapshot = await this.firestore.collection("users").doc(uid).get();
      if (!snapshot.exists) return null;
      const photo = snapshot.get("photo") as StoredMedia | undefined;
      return photo?.key ? photo : null;
    }
    return this.db.avatars[uid] ?? null;
  }

  async setAvatar(uid: string, media: StoredMedia): Promise<void> {
    if (this.firestore) {
      await this.firestore
        .collection("users")
        .doc(uid)
        .set(
          firestoreSafe({ photo: media, updatedAt: new Date().toISOString() }),
          { merge: true },
        );
      return;
    }
    this.db.avatars[uid] = media;
    this.persist();
  }

  async clearAvatar(uid: string): Promise<void> {
    if (this.firestore) {
      await this.firestore
        .collection("users")
        .doc(uid)
        .set({ photo: null }, { merge: true });
      return;
    }
    delete this.db.avatars[uid];
    this.persist();
  }

  // -- room covers -------------------------------------------------------

  async getCover(roomId: string): Promise<StoredMedia | null> {
    const key = safeId(roomId);
    if (this.firestore) {
      const snapshot = await this.firestore.collection("goatTeams").doc(key).get();
      if (!snapshot.exists) return null;
      const cover = snapshot.get("cover") as StoredMedia | undefined;
      return cover?.key ? cover : null;
    }
    return this.db.covers[key] ?? null;
  }

  async setCover(roomId: string, media: StoredMedia): Promise<void> {
    const key = safeId(roomId);
    if (this.firestore) {
      await this.firestore
        .collection("goatTeams")
        .doc(key)
        .set(firestoreSafe({ cover: media, updatedAt: new Date().toISOString() }), { merge: true });
      return;
    }
    this.db.covers[key] = media;
    this.persist();
  }

  async clearCover(roomId: string): Promise<void> {
    const key = safeId(roomId);
    if (this.firestore) {
      await this.firestore
        .collection("goatTeams")
        .doc(key)
        .set({ cover: null }, { merge: true });
      return;
    }
    delete this.db.covers[key];
    this.persist();
  }
}

export function createMediaStore(): MediaStore {
  return new MediaStore({ firestore: getFirebaseAdmin()?.firestore });
}

/**
 * Builds the shape the browser receives: the stored metadata plus a freshly
 * signed delivery url. Returns null when there is no image, so the UI can
 * fall back to initials.
 */
export function toMediaReference(
  stored: StoredMedia | null,
  purpose: MediaPurpose,
): MediaReference | null {
  if (!stored?.key) return null;
  const url = createDeliveryUrl(stored.key);
  if (!url) return null;
  return {
    key: stored.key,
    url,
    purpose,
    contentType: stored.contentType,
    size: stored.size,
    updatedAt: stored.updatedAt,
  };
}
